import{_ as a,a as l,c as s,ac as i}from"./chunks/framework.BSuaGltH.js";const k=JSON.parse('{"title":"ClickHouse：列式模型、类型与适用边界","description":"在现代列式说明中保留旧简介的选型与限制。","frontmatter":{"title":"ClickHouse：列式模型、类型与适用边界","description":"在现代列式说明中保留旧简介的选型与限制。","showdocs":{"topics":[{"id":"clickhouse","title":"ClickHouse","link":"/topics/clickhouse/"}],"kind":"列式模型与SQL","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"ClickHouse：列式分析与数据正确性","summary":"在现代列式说明中保留旧简介的选型与限制。","status":"active","related":[{"title":"ClickHouse：排序键、分区与版本","link":"/middleware/databases/clickhouse/plus/subjects/mergetree","kind":"引擎、导入与聚合","scope":"general","audience":"general"},{"title":"ClickHouse：批量导入与派生聚合","link":"/middleware/databases/clickhouse/plus/subjects/ingest","kind":"引擎、导入与聚合","scope":"general","audience":"general"},{"title":"ClickHouse：完整事件分析项目与解答","link":"/middleware/databases/clickhouse/plus/practice/application","kind":"完整事件项目","scope":"general","audience":"general"},{"title":"ClickHouse：诊断、异步变更与恢复","link":"/middleware/databases/clickhouse/plus/troubleshooting/diagnostics","kind":"诊断与恢复","scope":"general","audience":"general"},{"title":"ClickHouse：SQL筛选与聚合语义","link":"/middleware/databases/clickhouse/plus/subjects/sql","kind":"列式模型与SQL","scope":"general","audience":"general"}],"prev":false,"next":{"text":"ClickHouse：SQL筛选与聚合语义","link":"/middleware/databases/clickhouse/plus/subjects/sql"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"ClickHouse：SQL筛选与聚合语义","link":"/middleware/databases/clickhouse/plus/subjects/sql"}},"headers":[],"relativePath":"middleware/databases/clickhouse/foundations.md","filePath":"middleware/databases/clickhouse/foundations.md"}'),t={name:"middleware/databases/clickhouse/foundations.md"};function r(o,e,c,n,u,d){return l(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="clickhouse-列式模型、类型与适用边界" tabindex="-1">ClickHouse：列式模型、类型与适用边界 <a class="header-anchor" href="#clickhouse-列式模型、类型与适用边界" aria-label="Permalink to &quot;ClickHouse：列式模型、类型与适用边界&quot;">​</a></h1><h2 id="part-1" tabindex="-1">列式模型与分析边界 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;列式模型与分析边界 {#part-1}&quot;">​</a></h2><p>本课的表结构、六行输入与国家收入查询见<a href="/middleware/databases/clickhouse/plus/practice/application#source">完整事件分析工程</a>。前置：基础SQL阅读能力。适用：单节点ClickHouse 24.8 LTS基础语法；资料核对2026-10-17。示例未执行，本轮仅静态解析和文本审阅，不连接数据库、启动服务或调用产品接口。</p><h3 id="part-1-columns" tabindex="-1">ClickHouse 列式模型 <a class="header-anchor" href="#part-1-columns" aria-label="Permalink to &quot;ClickHouse 列式模型 {#part-1-columns}&quot;">​</a></h3><p>ClickHouse 列式模型把同一列的值按数据块组织，分析查询只选择需要的读取列，类似值排列有利于压缩。它并不意味着每个SELECT都快：如果扫描多数列、过滤不具选择性，仍会承担大量I/O和计算。先写出查询要的维度、度量、时间范围，再决定是否适合列式分析。</p><p>本课使用租户事件分析：event_id识别事件，tenant_id标识租户，event_time表示发生时刻，country是维度，amount是金额。问题是“一个月内某租户按国家的收入”，只需读取租户、时间、国家和金额；无需按行拿回所有事件内容。六行CSV用于核对语义，不能给出吞吐量或延迟结论。</p><p>与逐笔交易系统比较时，重点看访问方式。按主键读改一条订单、跨多表提交事务，与扫描历史事件分组是不同负载；同一业务可以把交易事实复制到分析层，但复制延迟和修正策略必须显式建模。不要用旧笔记的“毫秒级”和“上百亿行”作为容量承诺。</p><h3 id="part-1-types" tabindex="-1">ClickHouse 数据类型 <a class="header-anchor" href="#part-1-types" aria-label="Permalink to &quot;ClickHouse 数据类型 {#part-1-types}&quot;">​</a></h3><p>ClickHouse 数据类型应表达业务含义：金额选择Decimal保留定点小数，时间显式指定UTC，计数与标识使用无符号整数，低基数字符串可使用LowCardinality。Nullable只在缺失确有含义时使用，不能把未知金额默默当零。Decimal范围、乘除精度和转换行为需要按具体表达式检查；本例只汇总两位小数，不使用Float计算账款。</p><p>实践中amount是Decimal(12,2)，允许十位整数和两位小数，额外CHECK约束排除负数。UInt64的event_id能容纳重复值，因为类型只约束表示范围。DateTime(&#39;UTC&#39;)精度为秒；如事件排序需要毫秒，必须选择DateTime64并定义相同时间戳的决胜字段，不能只把文字里的“实时”理解为无限精度。</p><p>输入CSV中的时间文字没有时区偏移，本例明确按表的UTC解析。跨时区报表需决定按用户当地日还是UTC日统计；单纯把列类型换成另一个时区可能改变日界线含义。练习：北京时间1月1日00:30对应哪天UTC？解答是前一年12月31日16:30，因此按UTC日汇总不能直接当北京时间日报。</p><h3 id="part-1-scope" tabindex="-1">ClickHouse 一致性边界 <a class="header-anchor" href="#part-1-scope" aria-label="Permalink to &quot;ClickHouse 一致性边界 {#part-1-scope}&quot;">​</a></h3><p>ClickHouse 一致性边界先区分分析结果的新鲜度与事务承诺：单次INSERT的保障依赖表引擎、块、分区与副本配置，不能由“支持SQL”推导出任意跨表事务。异步写入、分布式转发、后台合并与派生汇总又各有完成条件。本课限定单节点MergeTree基础语法，不声称覆盖集群高可用或端到端恰好一次。</p><p>应用端应记录批次标识、逻辑事件键、提交状态与重试原因。网络断开时，“客户端没收到成功”并不等于“服务端没写入”；盲目重发有可能重复。反过来，异步写入确认收到缓冲区，也不一定等于持久写入完成。先定义什么证据才允许标记批次成功。</p><p>阅读顺序是先理解列与类型，再读SQL、排序键与分区，然后处理导入汇总，最后看完整实践与诊断恢复。每章均有独立解释与具体例子，可由目录直接进入；只需基础SQL阅读能力，本轮示例未执行。</p><h3 id="part-1-sources" tabindex="-1">官方依据与范围 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;官方依据与范围 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://clickhouse.com/docs/reference/data-types/decimal" target="_blank" rel="noopener noreferrer">ClickHouse官方资料 1</a>。</li><li><a href="https://clickhouse.com/docs/concepts/features/operations/insert/transactions" target="_blank" rel="noopener noreferrer">ClickHouse官方资料 2</a>。</li><li><a href="https://clickhouse.com/zh/use-cases/data-warehousing" target="_blank" rel="noopener noreferrer">ClickHouse官方资料 3</a>。</li></ul><p>中文与英文MergeTree、ReplacingMergeTree对照核对；翻译或当前文档包含的新功能不自动适用于24.8。本课没有运行该版本，只有静态证据。旧文<a href="#part-2">ClickHouse概述</a>保留原URL与正文，旧容量描述不作为本课性能结论。</p><h2 id="part-2" tabindex="-1">ClickHouse <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;ClickHouse {#part-2}&quot;">​</a></h2><p>ClickHouse 是一个用于实时分析的开源列式数据库管理系统 (DBMS)，它最初由俄罗斯的 Yandex 公司开发，并且在 2016 年开源。下面是一些关于 ClickHouse 的介绍、优缺点以及一些最大阈值的信息：</p><h3 id="part-2-介绍" tabindex="-1">介绍 <a class="header-anchor" href="#part-2-介绍" aria-label="Permalink to &quot;介绍 {#part-2-介绍}&quot;">​</a></h3><ul><li><strong>列式存储</strong> ：ClickHouse 是一个列式存储的数据库，这意味着它将数据按列而不是按行存储。这种存储方式使得它非常适合进行大规模的数据分析和聚合操作。</li><li><strong>高性能</strong> ：ClickHouse 的设计目标之一是提供高性能的数据查询和分析能力。它能够处理大量数据，并且在复杂的查询情况下保持高性能。</li><li><strong>分布式架构</strong> ：ClickHouse 支持分布式架构，可以水平扩展以处理大规模数据集。它可以通过添加更多的节点来增加存储容量和查询吞吐量。</li><li><strong>SQL 兼容性</strong> ：ClickHouse 支持 SQL 查询语言，这使得用户可以使用熟悉的语法进行数据分析和查询操作。</li><li><strong>实时数据分析</strong> ：尽管 ClickHouse 主要用于批处理分析，但它也具有一定的实时查询能力，可以满足一些实时数据分析的需求。</li></ul><h3 id="part-2-优点" tabindex="-1">优点 <a class="header-anchor" href="#part-2-优点" aria-label="Permalink to &quot;优点 {#part-2-优点}&quot;">​</a></h3><ul><li><strong>高性能</strong> ：ClickHouse 在处理大规模数据集时表现出色，可以快速执行复杂的分析查询。</li><li><strong>灵活性</strong> ：它支持 SQL 查询语言，并且可以与常见的 BI 工具和数据处理框架集成，使得用户能够以多种方式进行数据分析。</li><li><strong>易于扩展</strong> ：ClickHouse 支持分布式架构，可以通过添加更多的节点来水平扩展以处理更大的数据集。</li><li><strong>开源和社区支持</strong> ：作为一个开源项目，ClickHouse 拥有一个活跃的社区，用户可以从社区中获得支持和贡献新的功能和改进。</li></ul><h3 id="part-2-缺点" tabindex="-1">缺点 <a class="header-anchor" href="#part-2-缺点" aria-label="Permalink to &quot;缺点 {#part-2-缺点}&quot;">​</a></h3><ul><li><strong>实时性限制</strong> ：虽然 ClickHouse 具有一定的实时查询能力，但它主要用于批处理分析，对于需要实时数据更新和查询的应用场景可能不够适用。</li><li><strong>复杂性</strong> ：配置和管理 ClickHouse 集群可能需要一定的技术知识和经验，特别是在处理大规模数据时。</li><li><strong>存储格式转换成本</strong> ：由于 ClickHouse 使用列式存储，因此需要在存储和检索数据之间进行格式转换，这可能会导致一些额外的成本和复杂性。</li></ul><h3 id="part-2-最大阈值" tabindex="-1">最大阈值 <a class="header-anchor" href="#part-2-最大阈值" aria-label="Permalink to &quot;最大阈值 {#part-2-最大阈值}&quot;">​</a></h3><p>历史概述曾以“毫秒级响应”和“数十亿甚至上百亿行”描述能力，但未提供版本、硬件、数据模式、查询或测量来源，不能作为本课容量与延迟依据。实际评估应固定上述条件，记录读取列、扫描行数、并发、内存与查询耗时；六行教学数据只能核对查询语义。</p>',28)])])}const h=a(t,[["render",r]]);export{k as __pageData,h as default};
